begin;
with j as (select * from jsonb_to_recordset($law7d0055$[{"code_id":"NK_RF","article_number":"142.6","version_date":"2000-07-31","article_text":"1. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами, может быть использована федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и его территориальными орган\n\nами при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.2. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках международного автоматического обмена страновыми отчетами, не является самостоятельным доказательством неуплаты или неполной уплаты сумм налога (сбора) без исследования иных доказательств.Глава 203. ВЗАИМОСОГЛАСИТЕЛЬНАЯ ПРОЦЕДУРА В СООТВЕТСТВИИ С МЕЖДУНАРОДНЫМ ДОГОВОРОМ РОССИЙСКОЙ ФЕДЕРАЦИИ ПО ВОПРОСАМ НАЛОГООБЛОЖЕНИЯ(Дополнение главой - Федеральный закон от 29.09.2019 № 325-ФЗ)Статья 1427. Общие положенияВ целях настоящего Кодекса взаимосогласительной процедурой в соответствии с международным договором Российской Федерации по вопросам налогообложения (далее в настоящей главе - взаимосогласительная процедура) признается процедура разрешения споров о порядке налогообложения лица в отношении его доходов, прибыли и имущества при применении положений международного договора Российской Федерации по вопросам налогообложения.Статья 1428. Порядок проведения взаимосогласительной процедуры1. Порядок проведения взаимосогласительной процедуры определяется Министерством финансов Российской Федерации с учетом положений международных договоров Российской Федерации по вопросам налогообложения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)2. Взаимосогласительная процедура может быть инициирована по заявлению лица, указанного в статье 1427 настоящего Кодекса, или по запросу компетентного органа иностранного государства (территории), являющегося стороной международного договора Российской Федерации по вопросам налогообложения.3. Порядок и сроки представления заявления о проведении взаимосогласительной процедуры, а также порядок и сроки рассмотрения указанного заявления определяются Министерством финансов Российской Федерации с учетом положений международных договоров Российской Федерации по вопросам налогообложения.Статья 1429. Представление документов, сведений и иной информации в связи с проведением взаимосогласительной процедуры1. Лицо, обратившееся в Министерство финансов Российской Федерации с заявлением о проведении взаимосогласительной процедуры, обязано представить по запросу должностного лица налогового органа по месту учета такого лица документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.Документы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в сроки, установленные статьей 931 настоящего Кодекса.2. Министерство финансов Российской Федерации вправе запросить у лица, обратившегося с заявлением о проведении взаимосогласительной процедуры, не представленные ранее документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.Документы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в Министерство финансов Российской Федерации в течение одного месяца со дня получения соответствующего запроса.(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)Президент Российской Федерации                              Б.ЕльцинМосква, Кремль31 июля 1998 года№ 146-ФЗ\n\nами при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n2. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках международного автоматического обмена страновыми отчетами, не является самостоятельным доказательством неуплаты или неполной уплаты сумм налога (сбора) без исследования иных доказательств.\n\n(Дополнение главой - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 142.6. Ограничения использования информации, содержащейся в страновых отчетах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb19061769b4dc33823722eb6f40cee27c4bb8ac2dc780a900d61347cd3e7f0b"},{"code_id":"NK_RF","article_number":"142.7","version_date":"2000-07-31","article_text":"В целях настоящего Кодекса взаимосогласительной процедурой в соответствии с международным договором Российской Федерации по вопросам налогообложения (далее в настоящей главе - взаимосогласительная процедура) признается процедура разрешения споров о порядке налогообложения лица в отношении его доходов, прибыли и имущества при применении положений международного договора Российской Федерации по вопросам налогообложения.","article_title":"Статья 142.7. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05e627e10e6c5a3c3d710d46dd7d6fe547dd549e3a8d2b1f4e33cd0211e1db7a"},{"code_id":"NK_RF","article_number":"142.9","version_date":"2000-07-31","article_text":"1. Лицо, обратившееся в Министерство финансов Российской Федерации с заявлением о проведении взаимосогласительной процедуры, обязано представить по запросу должностного лица налогового органа по месту учета такого лица документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.\n\nДокументы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в сроки, установленные статьей 931 настоящего Кодекса.\n\n2. Министерство финансов Российской Федерации вправе запросить у лица, обратившегося с заявлением о проведении взаимосогласительной процедуры, не представленные ранее документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.\n\nДокументы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в Министерство финансов Российской Федерации в течение одного месяца со дня получения соответствующего запроса.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПрезидент Российской Федерации                              Б.Ельцин\n\nМосква, Кремль\n\n31 июля 1998 года","article_title":"Статья 142.9. Представление документов, сведений и иной информации в связи с проведением взаимосогласительной процедуры","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aaaa2a3ec577205bf9750d23d19cc93078b7914bb82e6f62b67d9bdcbf19c5a1"},{"code_id":"NK_RF","article_number":"15","version_date":"2000-07-31","article_text":"К местным налогам и сборам относятся:\n\n1) земельный налог;\n\n2) налог на имущество физических лиц;\n\n3) торговый сбор;\n\n4) туристический налог. (Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 29.11.2014 № 382-ФЗ)","article_title":"Статья 15. Местные налоги и сборы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"def43125de3eec9949d5b156246e705991565b30617ddd9d3b36a688046cd437"},{"code_id":"NK_RF","article_number":"16","version_date":"2000-07-31","article_text":"(Статья в редакции Федерального закона от 29.06.2004 № 58-ФЗ)","article_title":"Статья 16. Информация о налогах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"032b5baf0f7f054f942849068e2b4f49ac78d5f24ba8891c113d47f1e39c312d"},{"code_id":"NK_RF","article_number":"17","version_date":"2000-07-31","article_text":"объект налогообложения;\n\nналоговая база;\n\nналоговый период (за исключением налогов разового характера); (В редакции  Федерального закона от 04.08.2023 № 415-ФЗ)\n\nналоговая ставка;\n\nпорядок исчисления налога;\n\nпорядок и сроки уплаты налога.","article_title":"Статья 17. Общие условия установления налогов и сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f22768d802a54ecdc362ae9b67d48c435fe3219677383440c4d81b18489ae122"},{"code_id":"NK_RF","article_number":"18","version_date":"2000-07-31","article_text":"Специальные налоговые режимы могут предусматривать особый порядок определения элементов налогообложения, а также освобождение от обязанности по уплате отдельных налогов и сборов, предусмотренных статьями 13 - 15 настоящего Кодекса.\n\n1) система налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог);\n\n2) упрощенная система налогообложения;\n\n3) (Подпункт утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n4) система налогообложения при выполнении соглашений о разделе продукции;\n\n5) патентная система налогообложения; (Дополнение подпунктом - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\n6) налог на профессиональный доход (в порядке эксперимента); (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 425-ФЗ)\n\n7) \"Автоматизированная упрощенная система налогообложения\" (в порядке эксперимента). (Дополнение подпунктом - Федеральный закон от 25.02.2022 № 18-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)\n\n(Дополнение главой - Федеральный закон от 03.07.2016 № 243-ФЗ)","article_title":"Статья 18. Специальные налоговые режимы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13bd04ecca278c5ffe172d70c91991b6a8c4d6ce19e8634fecf326813d8b68f0"},{"code_id":"NK_RF","article_number":"18.1","version_date":"2000-07-31","article_text":"1. В Российской Федерации настоящим Кодексом устанавливаются страховые взносы, которые являются федеральными и обязательны к уплате на всей территории Российской Федерации.\n\n2. Страховые взносы отменяются настоящим Кодексом.","article_title":"Статья 18.1. Страховые взносы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ae6ff853562341359590de817f392fb3bed3dde3322a2599ed6d0d2677b6bd13"},{"code_id":"NK_RF","article_number":"18.2","version_date":"2000-07-31","article_text":"1. При установлении страховых взносов определяются в соответствии с главой 34 настоящего Кодекса плательщики и следующие элементы обложения:\n\n1) объект обложения страховыми взносами;\n\n2) база для исчисления страховых взносов;\n\n3) расчетный период;\n\n4) тариф страховых взносов;\n\n5) порядок исчисления страховых взносов;\n\n6) порядок и сроки уплаты страховых взносов.\n\n2. Элементы обложения страховыми взносами, указанные в подпунктах 1 и 2 пункта 1 настоящей статьи, могут определяться применительно к отдельным категориям плательщиков страховых взносов.\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 18.2. Общие условия установления страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d966570a98e2cf6a98de6a7e0435fcb8c01cf612b76e87492a8370063eb8b20"},{"code_id":"NK_RF","article_number":"19","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНалогоплательщиками, плательщиками сборов, плательщиками страховых взносов признаются организации и физические лица, на которых в соответствии с настоящим Кодексом возложена обязанность уплачивать соответственно налоги, сборы, страховые взносы. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nВ порядке, предусмотренном настоящим Кодексом, филиалы и иные обособленные подразделения российских организаций исполняют обязанности этих организаций по уплате налогов, сборов, страховых взносов по месту нахождения этих филиалов и иных обособленных подразделений. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nВ случаях, предусмотренных настоящим Кодексом, налогоплательщиками признаются иностранные структуры без образования юридического лица. (Дополнение частью - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 19. Налогоплательщики, плательщики сборов, плательщики страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02f167f6ae00d1ce7afc9fde174831e3c152121676134601bb52d4012d95ca95"},{"code_id":"NK_RF","article_number":"20","version_date":"2000-07-31","article_text":"1) одна организация непосредственно и (или) косвенно участвует в другой организации, и суммарная доля такого участия составляет более 20 процентов. Доля косвенного участия одной ор\n\nганизации в другой через последовательность иных организаций определяется в виде произведения долей непосредственного участия организаций этой последовательности одна в другой; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) одно физическое лицо подчиняется другому физическому лицу по должностному положению;\n\n3) лица состоят в соответствии с семейным законодательством Российской Федерации в брачных отношениях, отношениях родства или свойства, усыновителя и усыновленного, а также попечителя и опекаемого.","article_title":"Статья 20. Взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea9edb5ce99d4b95bf39d454a4fdd1e909ccce6d3bf00377376d4845ec79816b"},{"code_id":"NK_RF","article_number":"21","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Налогоплательщики имеют право:\n\n1) получать по месту своего учета от налоговых органов бесплатную информацию (в том числе в письменной форме) о действующих налогах и сборах, законодательстве о налогах и сборах и принятых в соответствии с ним нормативных правовых актах, порядке исчисления и уплаты налогов и сборов, правах и обязанностях налогоплательщиков, полномочиях налоговых органов и их должностных лиц, а также получать формы налоговых деклараций (расчетов) и разъяснения о порядке их заполнения; (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n2) получать от Министерства финансов Российской Федерации письменные разъяснения по вопросам применения законодательства Российской Федерации о налогах и сборах, от финансовых органов субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" - по вопросам применения соответственно законодательства субъектов Российской Федерации о налогах и сборах, нормативных правовых актов муниципальных образований о местных налогах и сборах, нормативных правовых актов представительного органа федеральной территории \"Сириус\" о местных налогах и сборах; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n3) использовать налоговые льготы при наличии оснований и в порядке, установленном законодательством о налогах и сборах;\n\n4) получать отсрочку, рассрочку или инвестиционный налоговый кредит в порядке и на условиях, установленных настоящим Кодексом; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n5) на своевременный возврат денежных средств в размере, не превышающем положительное сальдо единого налогового счета налогоплательщика, в порядке, предусмотренном настоящим Кодексом, или зачет указанных денежных средств в счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов, в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) либо в счет исполнения решений налоговых органов, указанных в подпунктах 10 и 11 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, в порядке, предусмотренном настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n51) на осуществление сверки принадлежности сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, либо сумм денежных средств, перечисленных не в качестве единого налогового платежа, а также на получение акта такой сверки; (Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n52) на основании представленного в налоговый орган запроса получать справки о наличии по состоянию на дату такого запроса положительного, отрицательного или нулевого сальдо единого налогового счета налогоплательщика, справки о принадлежности сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, и справки об исполнении обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов на основании данных налогового органа с учетом положений подпункта 10 пункта 1 статьи 32 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n6) представлять свои интересы в отношениях, регулируемых законодательством о налогах и сборах, лично либо через своего представителя; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n7) представлять налоговым органам и их должностным лицам пояснения по исчислению и уплате налогов, а также по актам проведенных налоговых проверок;\n\n8) присутствовать при проведении выездной налоговой проверки;\n\n9) получать копии акта налоговой проверки и решений налоговых органов, а также налоговые уведомления и требования об уплате задолженности;  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) требовать от должностных лиц налоговых органов и иных уполномоченных органов соблюдения законодательства о налогах и сборах при совершении ими действий в отношении налогоплательщиков; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n11) не выполнять неправомерные акты и требования налоговых органов, иных уполномоченных органов и их должностных лиц, не соответствующие настоящему Кодексу или иным федеральным законам; (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\n\n12) обжаловать в установленном порядке акты налоговых органов, иных уполномоченных органов и действия (бездействие) их должностных лиц; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)\n\n13) на соблюдение и сохранение налоговой тайны; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n14) на возмещение в полном объеме убытков, причиненных незаконными актами налоговых органов или незаконными действиями (бездействием) их должностных лиц; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n15) на участие в процессе рассмотрения материалов налоговой проверки или иных актов налоговых органов в случаях, предусмотренных настоящим Кодексом. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nПри представлении налогоплательщиком - физическим лицом документов (сведений) в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг днем их представления считается дата их приема многофункциональным центром предоставления государственных и муниципальных услуг. При этом налогоплательщику - физическому лицу многофункциональным центром предоставления государственных и муниципальных услуг выдается расписка или иной документ, подтверждающий прием документов (сведений).\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nДокументы (сведения), которые налогоплательщики - физические лица вправе представлять в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг, а также документы (сведения), содержащие налоговую тайну, которые направляются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, налогоплательщикам - физическим лицам в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг, определяются настоящим Кодексом или перечнем, утверждаемым в соответствии с абзацем первым пункта 9 статьи 31 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nПри представлении налогоплательщиком - физическим лицом документов (сведений) в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг днем их представления считается дата их направления налогоплательщиком - физическим лицом в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг. Информация о дне представления налогоплательщиком - физическим лицом документов (сведений) в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг размещается в личном кабинете на едином портале государственных и муниципальных услуг.\n\nДля прекращения получения от налоговых органов документов (сведений), используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг налогоплательщики - физические лица направляют в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг уведомление о прекращении получения документов (сведений) от налоговых органов в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг (далее - уведомление о прекращении получения документов с использованием единого портала государственных и муниципальных услуг). (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nПолучение от налоговых органов документов (сведений), используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг прекращается по истечении трех дней со дня представления налогоплательщиком - физическим лицом в налоговый орган уведомления о прекращении получения документов с использованием единого портала государственных и муниципальных услуг. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nНалогоплательщики - физические лица, ранее прекратившие получение от налоговых органов документов (сведений), не содержащих налоговую тайну, используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг в соответствии с абзацем четвертым настоящего пункта, в случае направления в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг уведомления о необходимости получения документов с использованием единого портала государственных и муниципальных услуг получают от налоговых органов в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг документы (сведения), используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, как содержащие, так и не содержащие налоговую тайну. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nУведомление о необходимости получения документов с использованием единого портала государственных и муниципальных услуг, уведомление о прекращении получения документов с использованием единого портала государственных и муниципальных услуг подписываются усиленной неквалифицированной электронной подписью, сертификат ключа проверки которой создан и используется в инфраструктуре, обеспечивающей информационно-технологическое взаимодействие информационных систем, используемых для предоставления государственных и муниципальных услуг в электронной форме, в установленном Правительством Российской Федерации порядке.\n\nФорма уведомления о необходимости получения документов с использованием единого портала государственных и муниципальных услуг, форма уведомления о прекращении получения документов с использованием единого портала государственных и муниципальных услуг, порядки заполнения таких форм и форматы представления таких уведомлений в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере информационных технологий.\n\n(Дополнение пунктом - Федеральный закон от 14.04.2023 № 125-ФЗ)\n\n2. Налогоплательщики имеют также иные права, установленные настоящим Кодексом и другими актами законодательства о налогах и сборах.","article_title":"Статья 21. Права налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a00c2c593c17e36db2e44692f4efd9bf16e2aa18d81f00d61bac62087b4dbd32"},{"code_id":"NK_RF","article_number":"22","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nПорядок защиты прав и законных интересов налогоплательщиков (плательщиков сборов, плательщиков страховых взносов) определяется настоящим Кодексом и иными федеральными законами. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНеисполнение или ненадлежащее исполнение обязанностей по обеспечению прав налогоплательщиков (плательщиков сборов, плательщиков страховых взносов) влечет ответственность, предусмотренную федеральными законами. (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 22. Обеспечение и защита прав налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4078d56f01e1b328819d99dd7719f0277963ef7c21877217c3b7db57af7e53ef"},{"code_id":"NK_RF","article_number":"23","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Налогоплательщики обязаны:\n\n1) уплачивать законно установленные налоги;\n\n2) встать на учет в налоговых органах, если такая обязанность предусмотрена настоящим Кодексом;\n\n3) вести в установленном порядке учет своих доходов (расходов) и объектов налогообложения, если такая обязанность предусмотрена законодательством о налогах и сборах;\n\n4) представлять в установленном порядке в налоговый орган по месту учета налоговые декларации (расчеты), уведомления об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов, уплаченных (перечисленных) в качестве единого налогового платежа, если такая обязанность предусмотрена законодательством о налогах и сборах; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) представлять в налоговый орган по месту жительства индивидуального предпринимателя, нотариуса, занимающегося частной практикой, адвоката, учредившего адвокатский кабинет, по запросу налогового органа книгу учета доходов и расходов и хозяйственных операций. В случае, если эти лица отнесены к категории крупнейших налогоплательщиков, книга учета доходов и расходов и хозяйственных операций представляется ими по запросу налогового органа в налоговый орган по месту их постановки на учет в качестве крупнейших налогоплательщиков; (В редакции  федеральных законов от 28.11.2018 № 447-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n51) представлять в налоговый орган по месту нахождения организации, у которой отсутствует обязанность представлять годовую бухгалтерскую (финансовую) отчетность, составляющую государственный информационный ресурс бухгалтерской (финансовой) отчетности в соответствии с Федеральным законом от 6 декабря 2011 года № 402-ФЗ \"О бухгалтерском учете\", годовую бухгалтерскую (финансовую) отчетность не позднее трех месяцев после окончания отчетного года, за исключением случаев, когда организация в соответствии с указанным Федеральным законом не обязана вести бухгалтерский учет, или является религиозной организацией, или является организацией, представляющей в Центральный банк Российской Федерации годовую бухгалтерскую (финансовую) отчетность, если иное не предусмотрено настоящим подпунктом.\n\nЦентральный банк Российской Федерации представляет в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, годовую бухгалтерскую (финансовую) отчетность Центрального банка Российской Федерации в составе годового баланса и отчета о финансовых результатах не позднее 15 мая года, следующего за отчетным годом;\n\n(Дополнение подпунктом - Федеральный закон от 28.11.2018 № 447-ФЗ)\n\n6) представлять в налоговые органы и их должностным лицам в случаях и в порядке, которые предусмотрены настоящим Кодексом, документы, необходимые для исчисления и уплаты налогов;\n\n7) выполнять законные требования налогового органа об устранении выявленных нарушений законодательства о налогах и сборах, а также не препятствовать законной деятельности должностных лиц налоговых органов при исполнении ими своих служебных обязанностей;\n\n8) в течение пяти лет обеспечивать сохранность данных бухгалтерского и налогового учета и других документов, необходимых для исчисления и уплаты налогов, в том числе документов, подтверждающих получение доходов, осуществление расходов (для организаций и индивидуальных предпринимателей), а также уплату (удержание) налогов, если иное не предусмотрено настоящим Кодексом; (В редакции федеральных законов от 30.09.2013 № 267-ФЗ, от 17.02.2021 № 6-ФЗ)\n\n9) нести иные обязанности, предусмотренные законодательством о налогах и сборах.\n\n2. Нал\n\nогоплательщики - организации и индивидуальные предприниматели помимо обязанностей, предусмотренных пунктом 1 настоящей статьи, обязаны сообщать в налоговый орган соответственно по месту нахождения организации, месту жительства индивидуального предпринимателя: (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n1) (Подпункт утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n11) (Дополнение подпунктом - Федеральный закон от 27.06.2011 № 162-ФЗ) (Утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n2) о своем участии в российских организациях (за исключением случаев участия в хозяйственных товариществах и обществах с ограниченной ответственностью) в случае, если доля прямого участия превышает 10 процентов, - в срок не позднее одного месяца со дня начала такого участия; (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\n3) обо всех обособленных подразделениях российской организации, созданных на территории Российской Федерации (за исключением филиалов и представительств), и изменениях в ранее сообщенные в налоговый орган сведения о таких обособленных подразделениях:\n\nв течение одного месяца со дня создания обособленного подразделения российской организации;\n\nв течение трех дней со дня изменения соответствующего сведения об обособленном подразделении российской организации;\n\n(Подпункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n31) обо всех обособленных подразделениях российской организации на территории Российской Федерации, через которые прекращается деятельность этой организации (которые закрываются этой организацией):\n\nв течение трех дней со дня принятия российской организацией решения о прекращении деятельности через филиал или представительство (закрытии филиала или представительства);\n\nв течение трех дней со дня прекращения деятельности российской организации через иное обособленное подразделение (закрытия иного обособленного подразделения);\n\n(Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n4) (Подпункт утратил силу - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\nУказанное сообщение с приложением копий правоустанавливающих (правоудостоверяющих) документов на объекты недвижимого имущества и (или) документов, подтверждающих государственную регистрацию транспортных средств, представляется в налоговый орган в отношении каждого объекта налогообложения однократно в срок до 31 декабря года, следующего за истекшим налоговым периодом.\n\nСообщение о наличии объекта налогообложения, указанное в абзаце первом настоящего пункта, не представляется в налоговый орган в случаях, если физическое лицо получало налоговое уведомление об уплате налога в отношении этого объекта или если не получало налоговое уведомление в связи с предоставлением ему налоговой льготы.\n\nСообщение о наличии объекта налогообложения и прилагаемые к нему копии документов, указанных в настоящем пункте, могут быть представлены в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\nСообщение о наличии объекта налогообложения с приложением копий документов, подтверждающих государственную регистрацию транспортных средств, и (или) правоустанавливающих (правоудостоверяющих) документов на объекты недвижимого имущества представляется в налоговый орган в отношении каждого объекта налогообложения однократно в срок до 31 декабря года, следующего за истекшим налоговым периодом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nСообщение о наличии объекта налогообложения не представляется в налоговый орган в случае, если организации было передано (направлено) сообщение об исчисленных налоговым органом суммах транспортного налога, налога на имущество организаций, земельного налога в отношении этого объекта или если организация применяет налоговую льготу в отношении соответствующего объекта налогообложения. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n1) о своем участии в иностранных организациях (в случае, если доля такого участия превышает 10 процентов). В целях настоящего подпункта доля участия в иностранной организации определяется в порядке, установленном статьей 1052 настоящего Кодекса;\n\n2) об учреждении иностранных структур без образования юридического лица; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n3) о контролируемых иностранных компаниях, в отношении которых они являются контролирующими лицами.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nПри наличии у иностранной организации (иностранной структуры без образования юридического лица) нескольких оснований для постановки на учет в налоговом органе сообщение представляется в налоговый орган по месту постановки на учет по выбору такой иностранной организации (иностранной структуры без образования юридического лица).\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\n34. Плательщики страховых взносов обязаны:\n\n1) уплачивать установленные настоящим Кодексом страховые взносы;\n\n2) вести учет объектов обложения страховыми взносами, сумм исчисленных страховых взносов по каждому физическому лицу, в пользу которого осуществлялись выплаты и иные вознаграждения, в соответствии с главой 34 настоящего Кодекса;\n\n3) представлять в установленном порядке в налоговый орган по месту учета расчеты по страховым взносам;\n\n4) представлять в налоговые органы и их должностным лицам в случаях и порядке, которые предусмотрены настоящим Кодексом, документы, необходимые для исчисления и уплаты страховых взносов;\n\n5) представлять в налоговые органы и их должностным лицам в случаях и порядке, которые предусмотрены настоящим Кодексом, сведения о застрахованных лицах в системе индивидуального (персонифицированного) учета;\n\n6) в течение шести лет обеспечивать сохранность документов, необходимых для исчисления и уплаты страховых взносов;\n\n7) сообщать в налоговый орган по месту нахождения российской организации - плательщика страховых взносов о наделении обособленного подразделения (включая филиал, представительство), созданного на территории Российской Федерации, которому открыт счет в банке, полномочиями (о лишении полномочий) начислять и производить выплаты и вознаграждения в пользу физических лиц в течение одного месяца со дня наделения его соответствующими полномочиями (лишения полномочий); (В редакции федеральных законов от 30.11.2016 № 401-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n8) нести иные обязанности, предусмотренные законодательством Российской Федерации о налогах и сборах.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nОбязанность лица, предусмотренная абзацем первым настоящего пункта, считается исполненной при наличии у него договора с оператором электронного документооборота на оказание услуг по обеспечению электронного документооборота (о передаче прав на использование программного обеспечения, предназначенного для обеспечения электронного документооборота) с указанным налоговым органом по месту учета этого лица и квалифицированного сертификата ключа проверки электронной подписи или при наличии такого договора и квалифицированного сертификата ключа проверки электронной подписи у уполномоченного представителя лица, которому предоставлены полномочия на получение документов от указанного налогового органа.\n\nВ случае, если получение от налогового органа документов осуществляется через уполномоченного представителя лица, на которое возложена обязанность, предусмотренная абзацем первым настоящего пункта, такая обязанность считается исполненной при наличии в указанном налоговом органе также документов, подтверждающих полномочия уполномоченного представителя лица - владельца указанного квалифицированного сертификата ключа проверки электронной подписи на получение документов от указанного налогового органа. При этом, если уполномоченным представителем лица является юридическое лицо, такая обязанность считается исполненной при наличии в указанном налоговом органе также документов, подтверждающих полномочия физического лица - владельца указанного сертификата ключа проверки электронной подписи на получение документов от указанного налогового органа (за исключением случаев, если физическое лицо является законным представителем такого юридического лица).\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nУказанное в абзаце первом настоящего пункта иностранное лицо должно обеспечить получение от налогового органа в электронной форме через личный кабинет налогоплательщика документов, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах.\n\nВ период, когда личный кабинет налогоплательщика не может использоваться таким иностранным лицом для представления в налоговый орган документов (информации), сведений, документы (информация), сведения, представление которых предусмотрено настоящим Кодексом, представляются таким иностранным лицом в налоговый орган в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nЕсли указанные сообщения переданы в электронной форме по телекоммуникационным каналам связи, такие сообщения должны быть заверены усиленной квалифицированной электронной подписью лица, представившего их, или усиленной квалифицированной электронной подписью его представителя. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nФормы и форматы сообщений, представляемых на бумажном носителе или в электронной форме, а также порядок заполнения форм указанных сообщений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nПорядок представления сообщений, предусмотренных пунктами 2, 21 и подпунктом 7 пункта 34 настоящей статьи, в электронной форме по телекоммуникационным каналам связи утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 02.04.2014 № 52-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 23. Обязанности налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"867fdb2a895798a54a796605d747962b1fc6e7b47c8c8b6cffc2dc705d51ad37"},{"code_id":"NK_RF","article_number":"24","version_date":"2000-07-31","article_text":"Обеспечение и защита прав налоговых агентов осуществляются в соответствии со статьей 22 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n1) правильно и своевременно исчислять, удерживать из денежных средств, выплачиваемых налогоплательщикам, и перечислять налоги в бюджетную систему Российской Федерации на соответствующие счета Федерального казначейства; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n2) письменно сообщать в налоговый орган по месту своего учета о невозможности удержать налог и о сумме задолженности налогоплательщика в течение одного месяца со дня, когда налоговому агенту стало известно о таких обстоятельствах; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n3) вести учет начисленных и выплаченных налогоплательщикам доходов, исчисленных, удержанных и перечисленных в бюджетную систему Российской Федерации налогов, в том числе по каждому налогоплательщику; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n4) представлять в налоговый орган по месту своего учета документы, необходимые для осуществления контроля за правильностью исчисления, удержания и перечисления налогов;\n\n5) в течение пяти лет обеспечивать сохранность документов, необходимых для исчисления, удержания и перечисления налогов. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nние возложенных на него обязанностей налоговый агент несет ответственность в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 24. Налоговые агенты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"875b1555248d972acf13c322e6e54cd93ff43f832394644360f5b6153c243443"},{"code_id":"NK_RF","article_number":"24.1","version_date":"2000-07-31","article_text":"1. Каждый налогоплательщик самостоятельно исполняет обязанности по уплате налога на прибыль организаций, налога на доходы физических лиц, возникающие в связи с его участием в договоре инвестиционного товарищества, с учетом особенностей, предусмотренных настоящей статьей и иными положениями настоящего Кодекса.\n\n2. Обязанность по уплате налогов и сборов, не указанных в пункте 1 настоящей статьи, но возникающих в связи с выполнением договора инвестиционного товарищества, возлагается на участника такого договора - управляющего товарища, ответственного за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета).\n\n3. Управляющий товарищ, ответственный за ведение налогового учета, признается налоговым агентом по доходам иностранных лиц от участия в инвестиционном товариществе.\n\n4. Управляющий товарищ, ответственный за ведение налогового учета, обязан:\n\n1) направлять в налоговый орган по месту своего учета копию договора инвестиционного товарищества (за исключением инвестиционной декларации), сообщать о его прекращении, сообщать о выполнении, прекращении выполнения функций управляющего товарища в срок не позднее пяти дней со дня заключения указанного договора, его прекращения, начала, прекращения выполнения функций управляющего товарища;\n\n2) вести обособленный налоговый учет по операциям инвестиционного товарищества в порядке, установленном главой 25 настоящего Кодекса;\n\n3) представлять в налоговый орган по месту своего учета расчет финансового результата инвестиционного товарищества.\n\nФорма расчета финансового результата инвестиционного товарищества утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\nРасчет финансового результата инвестиционного товарищества представляется в налоговый орган в сроки, установленные настоящим Кодексом для представления налоговой декларации (расчета) по налогу на прибыль организаций;\n\n4) (Подпункт утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n5) в порядке и в сроки, установленные договором инвестиционного товарищества, но не позднее пятнадцати дней до окончания срока представления в налоговый орган налоговых деклараций (расчетов) по налогу на прибыль организаций, установленных настоящим Кодексом, предоставлять участникам договора копию расчета финансового результата инвестиционного товарищества и сведения о приходящейся на каждого из них доле прибыли (убытка) инвестиционного товарищества.\n\nУправляющий товарищ предоставляет товарищам сведения о доле прибыли (убытка) инвестиционного товарищества, приходящейся на каждого из них, по каждому виду операций, доходы (расходы) по которым в соответствии с настоящим Кодексом определяются отдельно; (В редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\n6) предоставлять участникам договора инвестиционного товарищества сведения, предусмотренные Федеральным законом \"Об инвестиционных товариществах\";\n\n7) в случае, если в расчет финансового результата инвестиционного товарищества вносятся уточнения, представлять уточненный расчет в налоговый орган по месту своего учета и предоставлять участникам договора копию уточненного расчета финансового результата инвестиционного товарищества в течение пяти дней с даты внесения уточнений.\n\n5. Управляющий товарищ, ответственный за ведение налогового учета, в отношениях, связанных с ведением дел инвестиционного товарищества, имеет те же права, что и налогоплательщики.\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 24.1. Участие налогоплательщика в договоре инвестиционного товарищества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d3d0f4c814e2288a7c87043571116c48d9abbee98d04d2aeaa0781006ff1b9d"}]$law7d0055$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
